Функция НовыйНаборРегистров(ПервыеМинуты = 30, ВторыеМинуты = 45) Экспорт
    Клиент = Справочники.Клиенты.СоздатьЭлемент(); Клиент.Наименование = "Учебный P6 " + Строка(Новый УникальныйИдентификатор); Клиент.Записать();
    Услуга = Справочники.Услуги.СоздатьЭлемент(); Услуга.Наименование = "Учебная P6"; Услуга.Записать();
    Ссылки = Новый Массив;
    Для Индекс = 1 По 2 Цикл
        Документ = Документы.ЗаявкаУслуги.СоздатьДокумент(); Документ.Дата = Дата(2026,11,2,11+Индекс,0,0);
        Документ.Клиент = Клиент.Ссылка; Документ.Услуга = Услуга.Ссылка; Документ.Статус = Перечисления.СтатусыЗаявки.Новая;
        Документ.ДлительностьМинут = ?(Индекс = 1,ПервыеМинуты,ВторыеМинуты); Документ.Записать(); Ссылки.Добавить(Документ.Ссылка);
    КонецЦикла;
    Возврат Новый Структура("Клиент,Услуга,Первая,Вторая",Клиент.Ссылка,Услуга.Ссылка,Ссылки[0],Ссылки[1]);
КонецФункции

Функция ОпытРазбораОтказа() Экспорт
    Д = НовыйНаборРегистров();
    Объект = Д.Первая.ПолучитьОбъект();
    ОтказДиапазона = Ложь;
    Попытка
        Объект.ДлительностьМинут = 1441; Объект.Записать();
    Исключение
        ОтказДиапазона = Истина;
    КонецПопытки;
    ПослеОтказа = Д.Первая.ДлительностьМинут;
    ЗаписьЖурналаРегистрации("Nexus.P10.Диагностика",УровеньЖурналаРегистрации.Предупреждение,Метаданные.Документы.ЗаявкаУслуги,Д.Первая,"case=diagnostics-main; input=1441; range-rejected");
    Объект = Д.Первая.ПолучитьОбъект();
    Объект.ДлительностьМинут = 45; Объект.Записать();
    Возврат Новый Структура("Отказ,ПослеОтказа,ПослеПравки,Вторая",ОтказДиапазона,ПослеОтказа,Д.Первая.ДлительностьМинут,Д.Вторая.ДлительностьМинут);
КонецФункции

Процедура ПриНачалеРаботыСистемы()
    Р = УчебнаяНадёжность.ОпытРазбораОтказа();
    Сообщить("1441 отклонено: " + Строка(Р.Отказ));
    Сообщить("После отказа: " + Строка(Р.ПослеОтказа));
    Сообщить("После исправления: " + Строка(Р.ПослеПравки));
    Сообщить("Вторая сохранена: " + Строка(Р.Вторая));
КонецПроцедуры

